// Auth service of this workspace: a configured instance of @tecton/auth. Generated by
// `tecton-admin new`; the service code lives in the package, not here.
//
// Configuration comes from the environment and is validated before the service listens: the
// variables are listed in the README of @tecton/auth ("Running the service"). The required ones are
// TECTON_AUTH_DATABASE_URL, TECTON_AUTH_PEPPER, TECTON_AUTH_SIGNING_KEY and TECTON_VALKEY_URL.
// The start and migrate scripts load the workspace .env and then apps/auth/.env (copies of the
// .env.example files) when they exist: the Auth secrets live only in apps/auth/.env.
// Apply the database migrations first: pnpm --filter ./apps/auth migrate
import { startAuthServiceFromEnv } from '@tecton/auth';

const app = await startAuthServiceFromEnv(process.env);

// Graceful shutdown: finish in-flight requests before exiting (docker stop, Ctrl+C).
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(signal, () => {
    app.log.info({ signal }, 'shutting down');
    app.close().then(
      () => process.exit(0),
      (error: unknown) => {
        app.log.error({ err: error }, 'shutdown failed');
        process.exit(1);
      },
    );
  });
}
